_RAD_COLOR_PROPS = ("BackColor", "ForeColor")
_RAD_INT_PROPS = ("Left", "Top", "Width", "Height", "FontSize", "Value")


def _rad_rgb_hex(value):
    """'#rgb' / '#rrggbb' -> (r, g, b) or None."""
    s = str(value or "").strip()
    if not s.startswith("#"):
        return None
    s = s[1:]
    if len(s) == 3:
        s = "".join(ch * 2 for ch in s)
    try:
        return tuple(int(s[i:i + 2], 16) for i in (0, 2, 4)) if len(s) >= 6 else None
    except ValueError:
        return None


def _rad_ease(f, ease):
    if ease == "in":
        return f * f
    if ease == "out":
        return 1 - (1 - f) * (1 - f)
    if ease == "inout":
        return 2 * f * f if f < 0.5 else 1 - 2 * (1 - f) * (1 - f)
    if ease == "sine":
        return -(_math.cos(_math.pi * f) - 1) / 2
    if ease == "back":                              # overshoots a little, then settles
        return 1 + 2.70158 * (f - 1) ** 3 + 1.70158 * (f - 1) ** 2
    if ease == "elastic":
        if f <= 0 or f >= 1:
            return 1.0 if f >= 1 else 0.0
        return 2 ** (-10 * f) * _math.sin((f * 10 - 0.75) * (2 * _math.pi / 3)) + 1
    if ease == "bounce":
        n, d = 7.5625, 2.75
        if f < 1 / d:
            return n * f * f
        if f < 2 / d:
            f -= 1.5 / d
            return n * f * f + 0.75
        if f < 2.5 / d:
            f -= 2.25 / d
            return n * f * f + 0.9375
        f -= 2.625 / d
        return n * f * f + 0.984375
    return f


class _RadText(str):
    """Text being typed (typewriter keyframes): mixes by the length of the common prefix."""


def _rad_mix(prop, a, b, f, rgb):
    """Value of property *prop* between a (f = 0) and b (f = 1); rgb(colour) -> (r, g, b).
    Numbers follow f beyond 1 (back / elastic easings overshoot); colours and text stop at b."""
    if f <= 0:
        return a
    if prop in _RAD_COLOR_PROPS:
        if f >= 1:
            return b
        ca, cb = rgb(a), rgb(b)
        if ca is None or cb is None:
            return a
        return "#%02x%02x%02x" % tuple(max(0, min(255, int(round(x + (y - x) * f)))) for x, y in zip(ca, cb))
    if isinstance(a, bool) or isinstance(b, bool):
        return b if f >= 1 else a
    if isinstance(a, _RadText) or isinstance(b, _RadText):
        sa, sb = str(a or ""), str(b or "")
        if sa.startswith(sb) or sb.startswith(sa):
            longer = sa if len(sa) > len(sb) else sb
            n = len(sa) + (len(sb) - len(sa)) * min(f, 1.0)
            return _RadText(longer[:max(0, int(round(n)))])
        return b if f >= 1 else a
    try:
        x, y = float(a), float(b)
    except (TypeError, ValueError):
        return b if f >= 1 else a                  # Text...: discrete keyframes
    v = x + (y - x) * f
    return int(round(v)) if prop in _RAD_INT_PROPS else v


def _rad_resolve(prop, v, start, ref=None):
    """A keyframe value made absolute against *start* (the value when the animation starts):
    {"d": n} start + n, {"m": k} start * k, {"of": "Width", "f": x} start + x * start Width,
    {"reveal": 0..1} the start text up to that fraction, "$parent" the parent's background colour;
    ref(prop) = start value of another property of the same control (ref("$parent") = parent colour)."""
    if isinstance(v, str) and v == "$parent":
        c = ref("$parent") if ref is not None else None
        return c if c else start
    if not isinstance(v, dict):
        return v
    if "reveal" in v:
        s = "" if start is None else str(start)
        try:
            f = max(0.0, min(1.0, float(v["reveal"])))
        except (TypeError, ValueError):
            f = 1.0
        return _RadText(s[:int(round(len(s) * f))])
    if isinstance(start, bool) or start is None:
        return start
    try:
        x = float(start)
    except (TypeError, ValueError):
        return start                               # colours / text: relative keys keep the start value
    try:
        val = x * float(v.get("m", 1)) + float(v.get("d", 0))
        if v.get("of"):
            other = ref(str(v["of"])) if ref is not None else None
            val += float(v.get("f", 0)) * float(other if other is not None else 0)
    except (TypeError, ValueError):
        return start
    if prop in _RAD_INT_PROPS:
        return int(round(val))
    return max(0.0, min(1.0, val)) if prop == "Opacity" else val


def _rad_resolve_keys(prop, keys, start, ref=None):
    """Keyframes [(ms, value, ease)] with relative values made absolute (see _rad_resolve)."""
    return [(k[0], _rad_resolve(prop, k[1], start, ref)) + tuple(k[2:]) for k in keys]


def _rad_has_relative(keys):
    return any(isinstance(k[1], dict) or (isinstance(k[1], str) and k[1] == "$parent") for k in keys)


def _rad_value_at(prop, keys, t, start, rgb):
    """keys = [(ms, value, ease), ...] sorted by time; start = value before the first key."""
    if not keys:
        return start
    pts = list(keys)
    if pts[0][0] > 0 and start is not None:
        pts.insert(0, (0, start, ""))
    if t <= pts[0][0]:
        return pts[0][1]
    for (t0, v0, _e0), (t1, v1, e1) in zip(pts, pts[1:]):
        if t <= t1:
            f = (t - t0) / (t1 - t0) if t1 > t0 else 1.0
            return _rad_mix(prop, v0, v1, _rad_ease(f, e1), rgb)
    return pts[-1][1]


class _Storyboard:
    """Storyboard (Expression Blend): keyframe animation of control properties.
    Begin() starts from time 0, Stop() stops and puts the animated properties back, Pause() / Resume(),
    Seek(ms), Reverse() plays back to time 0; at the end the last values stay (HoldEnd), the callables in
    Completed run and then the form's <Name>_Completed(). RepeatForever, Count (plays) and AutoReverse can
    be changed before Begin(). Keyframe values may be relative to the values at Begin ({"d": -50} ...)."""

    def __init__(self, owner, io, name, tracks, repeat=False, autoreverse=False, count=1):
        self._o, self._io, self.Name = owner, io, name
        self._raw = [(t, p, sorted(((k[0], k[1], k[2] if len(k) > 2 else "") for k in keys), key=lambda k: k[0]))
                     for t, p, keys in tracks]
        self.Tracks = self._raw
        self.RepeatForever, self.AutoReverse = bool(repeat), bool(autoreverse)
        self.Count = max(1, int(count or 1))
        self.Duration = max([k[0] for _t, _p, keys in self._raw for k in keys] or [0])
        self.IsPlaying, self.Position = False, 0
        self.Completed = []                 # callables run when the storyboard ends (chains)
        self._gen, self._saved, self._t0, self._paused, self._rev, self._last = 0, {}, 0.0, None, False, {}

    def _remember(self):
        if self._saved:
            return
        self._saved = {(t, p): self._io.get(t, p) for t, p, _k in self._raw}
        self._last = {}
        if not any(_rad_has_relative(keys) for _t, _p, keys in self._raw):
            self.Tracks = self._raw
            return

        def ref(t):
            def get(prop):
                if prop == "$parent":
                    fn = getattr(self._io, "parent_bg", None)
                    return fn(t) if fn is not None else None
                if (t, prop) not in self._saved:
                    self._saved[(t, prop)] = self._io.get(t, prop)
                return self._saved[(t, prop)]
            return get
        self.Tracks = [(t, p, _rad_resolve_keys(p, keys, self._saved.get((t, p)), ref(t)))
                       for t, p, keys in self._raw]
        self._saved = {k: v for k, v in self._saved.items() if any(k == (t, p) for t, p, _k in self._raw)}

    def _apply(self, ms):
        self.Position = ms
        for t, p, keys in self.Tracks:
            v = _rad_value_at(p, keys, ms, self._saved.get((t, p)),
                              lambda c, t=t, p=p: self._io.rgb(t, p, c))
            if self._last.get((t, p), self) == v and p == "Visible":
                continue                    # (re-showing every frame re-places the widget)
            self._last[(t, p)] = v
            self._io.set(t, p, v)

    def Begin(self):
        self._remember()
        self._gen += 1
        self.IsPlaying, self._paused, self._rev = True, None, False
        self._t0 = _time.monotonic()
        self._tick(self._gen)

    def Reverse(self):
        """Play from the current position back to time 0 (then Stop(): the values are back)."""
        if not self._saved:
            return
        self._gen += 1
        self.IsPlaying, self._paused, self._rev = True, None, True
        self._t0 = _time.monotonic() - (self.Duration - min(self.Position, self.Duration)) / 1000.0
        self._tick(self._gen)

    def _tick(self, gen):
        if gen != self._gen or not self.IsPlaying:
            return
        ms = (_time.monotonic() - self._t0) * 1000.0
        if self._rev:
            pos = self.Duration - ms
            if pos <= 0:
                self.Stop()
                return
            self._apply(pos)
            self._io.later(15, lambda: self._tick(gen))
            return
        span = self.Duration * (2 if self.AutoReverse else 1)
        total = span * self.Count
        done = False
        if span <= 0:
            ms, done = 0, True
        elif self.RepeatForever:
            if ms >= span:
                self._t0 += (ms // span) * span / 1000.0
                ms %= span
        elif ms >= total:
            ms, done = span, True
        else:
            ms %= span
        self._apply(ms if ms <= self.Duration else span - ms)
        if done:
            self._completed()
            return
        self._io.later(15, lambda: self._tick(gen))

    def _completed(self):
        self.IsPlaying = False
        for fn in list(self.Completed):
            fn()
        fn = getattr(self._o, self.Name + "_Completed", None)
        if callable(fn):
            fn()

    def Finish(self):
        """Jump to the end at once (reduced motion) and run the Completed callbacks."""
        self._remember()
        self._gen += 1
        self._paused = None
        self._apply(0 if self.AutoReverse else self.Duration)
        self._completed()

    def Stop(self):
        self._gen += 1
        self.IsPlaying, self._paused, self.Position, self._rev = False, None, 0, False
        for (t, p), v in self._saved.items():
            self._io.set(t, p, v)
            if p in ("Left", "Top", "Width", "Height"):
                self._io.release(t, p)          # Anchor / Dock take the control back
        self._saved, self._last = {}, {}

    def Pause(self):
        if self.IsPlaying:
            self._gen += 1
            self.IsPlaying = False
            self._paused = _time.monotonic() - self._t0

    def Resume(self):
        if self._paused is not None:
            self._t0 = _time.monotonic() - self._paused
            self._paused = None
            self.IsPlaying = True
            self._gen += 1
            self._tick(self._gen)

    def Seek(self, ms):
        self._remember()
        ms = max(0, min(float(ms), self.Duration))
        self._apply(ms)
        if self.IsPlaying:
            self._t0 = _time.monotonic() - ms / 1000.0
        elif self._paused is not None:
            self._paused = ms / 1000.0


def _rad_fx_scale(s0, s1, d, e, transform, form):
    """Scale from factor s0 to s1 (transform targets) or the Width / Height around the centre."""
    if transform:
        return [("ScaleX", [[0, {"m": s0}], [d, {"m": s1}, e]]), ("ScaleY", [[0, {"m": s0}], [d, {"m": s1}, e]])]
    out = [("Width", [[0, {"m": s0}], [d, {"m": s1}, e]]), ("Height", [[0, {"m": s0}], [d, {"m": s1}, e]])]
    if not form:
        out += [("Left", [[0, {"of": "Width", "f": (1 - s0) / 2.0}], [d, {"of": "Width", "f": (1 - s1) / 2.0}, e]]),
                ("Top", [[0, {"of": "Height", "f": (1 - s0) / 2.0}], [d, {"of": "Height", "f": (1 - s1) / 2.0}, e]]),
                ("FontSize", [[0, {"m": max(s0, 0.3)}], [d, {"m": max(s1, 0.3)}, e]])]
    return out


def _rad_fx_fade(a0, a1, d, e, alpha, form):
    """Opacity a0 -> a1 (1 = the start value), or a colour blend into the parent background."""
    if alpha or form:
        v0 = {"d": 0} if a0 >= 1 else float(a0)
        v1 = {"d": 0} if a1 >= 1 else float(a1)
        return [("Opacity", [[0, v0], [d, v1, e]])]
    c0 = {"d": 0} if a0 >= 1 else "$parent"
    c1 = {"d": 0} if a1 >= 1 else "$parent"
    return [("BackColor", [[0, c0], [d, c1, e]]), ("ForeColor", [[0, c0], [d, c1, e]])]


def _rad_fx_slide(side, dist):
    side = str(side or "left").lower()
    prop = "Top" if side in ("top", "bottom", "up", "down") else "Left"
    sign = -1 if side in ("left", "top", "up") else 1
    return prop, sign * abs(float(dist))


def _rad_fx_tracks(preset, params=None, dur=500, ease="out", alpha=False, transform=False, form=False):
    """Keyframe tracks [(prop, keys)] of *preset* plus a note ("" or how this target shows it)."""
    p = dict(params or {})
    d = max(1, int(dur or 1))
    e = str(ease or "")
    e = "" if e == "linear" else e
    show = [] if form else [("Visible", [[0, True]])]
    hide = [] if form else [("Visible", [[0, {"d": 0}], [d, False]])]
    note = ""
    if preset == "fadeIn":
        tr = show + _rad_fx_fade(0, 1, d, e, alpha, form)
        if not (alpha or form):
            note = "fades as a colour blend into the background (no transparency)"
        return tr, note
    if preset == "fadeOut":
        tr = _rad_fx_fade(1, 0, d, e, alpha, form) + hide
        if not (alpha or form):
            note = "fades as a colour blend into the background (no transparency)"
        return tr, note
    if preset == "move":
        dx, dy = float(p.get("dx", 100) or 0), float(p.get("dy", 0) or 0)
        tr = []
        if dx:
            tr.append(("Left", [[0, {"d": 0}], [d, {"d": dx}, e]]))
        if dy:
            tr.append(("Top", [[0, {"d": 0}], [d, {"d": dy}, e]]))
        return tr, note
    if preset in ("slideIn", "slideOut"):
        side = p.get("from", p.get("to", "left"))
        prop, off = _rad_fx_slide(side, p.get("distance", 80))
        fade = bool(p.get("fade", True)) and (alpha or form)
        if preset == "slideIn":
            tr = show + [(prop, [[0, {"d": off}], [d, {"d": 0}, e]])]
            if fade:
                tr += _rad_fx_fade(0, 1, d, e, True, form)
        else:
            tr = [(prop, [[0, {"d": 0}], [d, {"d": off}, e or "in"]])]
            if fade:
                tr += _rad_fx_fade(1, 0, d, e or "in", True, form)
            tr += hide
        return tr, note
    if preset == "bounce":
        h = abs(float(p.get("height", 20) or 20))
        return [("Top", [[0, {"d": 0}], [int(d * 0.3), {"d": -h}, "out"], [int(d * 0.55), {"d": 0}, "in"],
                         [int(d * 0.75), {"d": -h * 0.4}, "out"], [d, {"d": 0}, "in"]])], note
    if preset == "shake":
        a = abs(float(p.get("distance", 10) or 10))
        steps = [0, -a, a, -a, a, -a * 0.5, 0]
        n = len(steps) - 1
        return [("Left", [[int(d * i / n), {"d": v}] for i, v in enumerate(steps)])], note
    if preset == "pulse":
        s = float(p.get("scale", 1.08) or 1.08)
        a = _rad_fx_scale(1, s, d // 2, "inout", transform, form)
        b = _rad_fx_scale(s, 1, d, "inout", transform, form)
        tr = [(pa, ka + kb[1:]) for (pa, ka), (_pb, kb) in zip(a, b)]
        if not transform:
            note = "pulses by resizing (no scale transform)"
        return tr, note
    if preset == "rotate":
        ang = float(p.get("angle", 360) or 360)
        if transform:
            return [("Rotation", [[0, {"d": 0}], [d, {"d": ang}, e]])], note
        w = 6
        steps = [0, -w, w, -w, w, 0]
        n = len(steps) - 1
        return ([("Left", [[int(d * i / n), {"d": v}] for i, v in enumerate(steps)])],
                "rotation is shown as a wobble (no rotation)")
    if preset == "flip":
        axis = str(p.get("axis", "x")).lower()
        if transform:
            prop = "ScaleY" if axis == "y" else "ScaleX"
            return [(prop, [[0, {"m": -1}], [d, {"m": 1}, e]])], note
        size, pos = ("Height", "Top") if axis == "y" else ("Width", "Left")
        h = d // 2
        tr = [(size, [[0, {"m": 1}], [h, {"m": 0}, "in"], [d, {"m": 1}, "out"]])]
        if not form:
            tr.append((pos, [[0, {"d": 0}], [h, {"of": size, "f": 0.5}, "in"], [d, {"d": 0}, "out"]]))
        return tr, "flips by narrowing the control (no 3D transform)"
    if preset in ("scaleIn", "scaleOut", "zoom"):
        s = float(p.get("scale", 0.3 if preset != "zoom" else 1.2) or 0.3)
        if preset == "scaleIn":
            tr = show + _rad_fx_scale(s, 1, d, e or "out", transform, form)
            if alpha or form:
                tr += _rad_fx_fade(0, 1, d, e, True, form)
        elif preset == "scaleOut":
            tr = _rad_fx_scale(1, s, d, e or "in", transform, form)
            if alpha or form:
                tr += _rad_fx_fade(1, 0, d, e or "in", True, form)
            tr += hide
        else:
            tr = _rad_fx_scale(1, s, d, e, transform, form)
        if not transform:
            note = "scales by resizing around the centre (no scale transform)"
        return tr, note
    if preset == "colorTo":
        prop = "ForeColor" if str(p.get("prop", "BackColor")) == "ForeColor" else "BackColor"
        color = str(p.get("color") or "#3399ff")
        return [(prop, [[0, {"d": 0}], [d, color, e]])], note
    if preset == "typewriter":
        return [("Text", [[0, {"reveal": 0}], [d, {"reveal": 1}]])], note
    return [], "unknown preset '%s'" % preset


