def _rad_reduced_motion():
    """True when the system asks for less motion (RADIDE_REDUCED_MOTION=1, or Windows animations off)."""
    import os as _os
    v = _os.environ.get("RADIDE_REDUCED_MOTION", "").strip().lower()
    if v:
        return v in ("1", "true", "yes", "on")
    if _os.name == "nt":
        try:
            import ctypes
            on = ctypes.c_int(1)
            if ctypes.windll.user32.SystemParametersInfoW(0x1042, 0, ctypes.byref(on), 0):  # CLIENTAREAANIMATION
                return not on.value
        except (AttributeError, OSError, ValueError):
            pass
    return False


class _RadQuietIO:
    """Writes of the animations themselves: their Visible changes do not start show / hide animations."""

    def __init__(self, io):
        self._io = io

    def __getattr__(self, name):
        return getattr(self._io, name)

    def set(self, name, prop, v):
        self._io.quiet = getattr(self._io, "quiet", 0) + 1
        try:
            self._io.set(name, prop, v)
        finally:
            self._io.quiet -= 1


class _RadFx:
    """Animations designed in the Animations window: triggers (load, click, hover, timer, show, hide,
    after another animation, manual), chains, reduced motion and Animate() from code."""

    def __init__(self, owner, io, storyboards, triggers, reduced=True, alpha=False, transform=False):
        self._o, self._io, self._qio = owner, io, _RadQuietIO(io)
        self.Storyboards, self._meta = {}, {}
        self.Triggers = list(triggers)
        self.ReducedMotion = bool(reduced) and _rad_reduced_motion()
        self._alpha, self._transform = bool(alpha), bool(transform)
        self._timers, self._pending, self._show, self._hide = {}, {}, {}, {}
        for d in storyboards:
            sb = _Storyboard(owner, self._qio, d["name"], d["tracks"], repeat=d.get("repeat", False),
                             autoreverse=d.get("autoreverse", False), count=d.get("count", 1))
            self._add(d["fx"], sb, d.get("delayMs", 0), d.get("restore", False), d.get("target", ""))
            try:
                setattr(owner, d["name"], sb)           # self._fx_fx1.Begin() works too
            except AttributeError:
                pass
        io.vis_hook = self._visible
        for t in self.Triggers:
            self._arm(t)

    def _add(self, fx, sb, delay, restore, target):
        self.Storyboards[fx] = sb
        self._meta[fx] = {"delay": int(delay or 0), "restore": bool(restore), "target": target or "",
                          "hiding": False}
        sb.Completed.insert(0, lambda: self._done(fx))

    # ------------------------------------------------------------ triggers
    def _arm(self, t):
        fx, on, src = t.get("fx"), t.get("on"), t.get("source") or ""
        bind = getattr(self._io, "bind", None)
        try:
            if on == "click" and bind is not None:
                bind(src, "click", lambda: self.Begin(fx))
            elif on == "hover" and bind is not None:
                bind(src, "enter", lambda: self.Begin(fx))
                leave = t.get("leave", "reverse")
                if leave == "reverse":
                    bind(src, "leave", lambda: self._reverse(fx))
                elif leave == "stop":
                    bind(src, "leave", lambda: self.Stop(fx))
            elif on == "after":
                sb = self.Storyboards.get(t.get("after"))
                if sb is not None:
                    sb.Completed.append(lambda: self.Begin(fx))
            elif on == "show":
                self._show.setdefault(t.get("target") or "", []).append(fx)
            elif on == "hide":
                self._hide.setdefault(t.get("target") or "", []).append(fx)
        except (AttributeError, KeyError):
            pass                                        # a control that is not there (any more)

    def start(self):
        """After <Form>_Load: animations "On load" begin, "On timer" ones start their timers."""
        for t in self.Triggers:
            if t.get("on") == "load":
                self.Begin(t["fx"])
            elif t.get("on") == "timer" and int(t.get("intervalMs") or 0) > 0:
                tok = object()
                self._timers[t["fx"]] = tok
                ms = int(t["intervalMs"])
                self._io.later(ms, lambda fx=t["fx"], ms=ms, tok=tok: self._every(fx, ms, tok))

    def _every(self, fx, ms, tok):
        if self._timers.get(fx) is not tok:
            return
        self.Begin(fx)
        self._io.later(ms, lambda: self._every(fx, ms, tok))

    def _visible(self, name, on):
        """_RadIO.set(name, "Visible", on) hook: True = handled here (the hide plays first)."""
        if getattr(self._io, "quiet", 0):
            return False
        fxs = [fx for fx in (self._show if on else self._hide).get(name, ()) if fx in self.Storyboards]
        if not fxs or bool(self._io.get(name, "Visible")) == bool(on):
            return False
        if on:
            self._qio.set(name, "Visible", True)
            for fx in fxs:
                self.Begin(fx)
        else:
            for fx in fxs:
                self._meta[fx]["hiding"] = True
                self.Begin(fx)
        return True

    def _done(self, fx):
        m = self._meta.get(fx)
        sb = self.Storyboards.get(fx)
        if m is None or sb is None:
            return
        if m["hiding"]:
            m["hiding"] = False
            sb.Stop()                                   # designed values back, then hidden
            self._qio.set(m["target"], "Visible", False)
        elif m["restore"]:
            sb.Stop()                                   # ended where it started: Anchor / Dock take over

    def _reverse(self, fx):
        sb = self.Storyboards.get(fx)
        if sb is None:
            return
        self._pending.pop(fx, None)
        if self.ReducedMotion:
            sb.Stop()
        else:
            sb.Reverse()

    # ------------------------------------------------------------ API
    def _find(self, fx):
        fx = str(fx or "")
        if fx in self.Storyboards:
            return fx
        return next((k for k, sb in self.Storyboards.items() if sb.Name == fx), None)

    def Begin(self, fx):
        fx = self._find(fx)
        if fx is None:
            return False
        sb = self.Storyboards[fx]
        if self.ReducedMotion:
            if not sb.IsPlaying:
                sb._saved = {}
            sb.Finish()
            return True
        if not sb.IsPlaying:
            sb._saved = {}                              # start from the values the control has now
        delay = self._meta[fx]["delay"]
        if delay > 0:
            tok = object()
            self._pending[fx] = tok
            sb.Seek(0)                                  # first frame now (e.g. slid out), then wait

            def go():
                if self._pending.get(fx) is tok:
                    del self._pending[fx]
                    sb.Begin()
            self._io.later(delay, go)
        else:
            sb.Begin()
        return True

    def Stop(self, fx):
        fx = self._find(fx)
        if fx is None:
            return False
        self._timers.pop(fx, None)
        self._pending.pop(fx, None)
        self._meta[fx]["hiding"] = False
        self.Storyboards[fx].Stop()
        return True

    def SetVisible(self, target, visible):
        target = self._name(target)
        if not self._visible(target, bool(visible)):
            self._qio.set(target, "Visible", bool(visible))

    def _name(self, target):
        if target is None or isinstance(target, str):
            return target or ""
        name = getattr(target, "_rad_name", None)
        if name:
            return name
        for k, v in vars(self._o).items():
            if v is target:
                return k
        return ""

    def Animate(self, target, preset, **opts):
        """Play *preset* on *target* now; returns its storyboard (Stop() / Pause() ...)."""
        target = self._name(target)
        dur0, ease0, restores = _RAD_FX_DEFAULTS.get(preset, (500, "out", True))
        dur = opts.pop("durationMs", opts.pop("duration", dur0))
        delay = opts.pop("delayMs", opts.pop("delay", 0))
        ease = opts.pop("easing", opts.pop("ease", ease0))
        rep = int(opts.pop("repeat", 1) or 0)
        rev = bool(opts.pop("autoreverse", False))
        params = {k.rstrip("_"): v for k, v in opts.items()}      # from_="right" -> from
        tracks, _note = _rad_fx_tracks(preset, params, dur, ease, self._alpha or not target, self._transform,
                                       not target)
        if not tracks:
            raise ValueError("unknown animation preset %r" % (preset,))
        fx = "adhoc:%s:%s" % (target, preset)
        old = self.Storyboards.get(fx)
        if old is not None and old.IsPlaying:
            old.Stop()
        sb = _Storyboard(self._o, self._qio, "_fx_adhoc", [(target, p, k) for p, k in tracks],
                         repeat=rep == 0, autoreverse=rev, count=max(1, rep))
        self._add(fx, sb, delay, restores or rev, target)
        self.Begin(fx)
        return sb


class _RadStateEvents(QObject):
    """Feeds MouseOver / Pressed / Focused / Disabled of one widget to the visual state manager."""

    def __init__(self, widget, name, vsm):
        super().__init__(widget)
        self.w, self.name, self.vsm = widget, name, vsm
        self.map = {QEvent.Type.Enter: ("MouseOver", True), QEvent.Type.Leave: ("MouseOver", False),
                    QEvent.Type.MouseButtonPress: ("Pressed", True),
                    QEvent.Type.MouseButtonRelease: ("Pressed", False),
                    QEvent.Type.FocusIn: ("Focused", True), QEvent.Type.FocusOut: ("Focused", False)}
        widget.installEventFilter(self)
        vp = getattr(widget, "viewport", None)
        if callable(vp):
            vp().installEventFilter(self)
        if not widget.isEnabled():
            vsm.Flag(name, "Disabled", True)

    def eventFilter(self, obj, ev):
        t = ev.type()
        if t == QEvent.Type.EnabledChange and obj is self.w:
            self.vsm.Flag(self.name, "Disabled", not self.w.isEnabled())
        elif t in self.map:
            state, on = self.map[t]
            self.vsm.Flag(self.name, state, on)
        return False


class _RadFxEvents(QObject):
    """Click / mouse enter / leave of one widget starts an animation (Animations window triggers)."""

    def __init__(self, widget, event, fn):
        super().__init__(widget)
        self.w, self.fn = widget, fn
        self.t = {"click": QEvent.Type.MouseButtonRelease, "enter": QEvent.Type.Enter,
                  "leave": QEvent.Type.Leave}[event]
        widget.installEventFilter(self)

    def eventFilter(self, obj, ev):
        if obj is self.w and ev.type() == self.t:
            inside = True
            if self.t == QEvent.Type.MouseButtonRelease:
                try:
                    inside = self.w.rect().contains(ev.position().toPoint())
                except AttributeError:
                    pass
            if inside:
                self.fn()
        return False


class _RadIO:
    """Reads / writes neutral properties of the Qt widgets (visual states, storyboards, bindings)."""
    vis_hook = None         # animations: callable(name, visible) -> True when it handles the change
    quiet = 0               # > 0 while the animations write (no show / hide hooks)

    def __init__(self, owner):
        self.o = owner
        self._colors, self._base_ss, self._events = {}, {}, []

    def w(self, name):
        return self.o if not name else getattr(self.o, name)

    def get(self, name, prop):
        try:
            w = self.w(name)
            if prop == "Text":
                if not name:
                    return w.windowTitle()
                if isinstance(w, QPlainTextEdit):
                    return w.toPlainText()
                if isinstance(w, QGroupBox):
                    return w.title()
                if isinstance(w, QComboBox):
                    return w.currentText()
                return w.text() if hasattr(w, "text") else ""
            if prop == "Left":
                return w.x()
            if prop == "Top":
                return w.y()
            if prop == "Width":
                return w.width()
            if prop == "Height":
                return w.height() - self._top() if not name else w.height()
            if prop in ("BackColor", "ForeColor"):
                return self._colors.get(name, {}).get(prop, "")
            if prop == "Visible":
                return not w.isHidden()
            if prop == "FontSize":
                return w.font().pointSize()
            if prop == "FontBold":
                return w.font().bold()
            if prop == "FontItalic":
                return w.font().italic()
            if prop == "Opacity":
                if not name:
                    return w.windowOpacity()
                eff = w.graphicsEffect()
                return eff.opacity() if isinstance(eff, QGraphicsOpacityEffect) else 1.0
            if prop == "Value":
                return w.value()
            if prop == "Checked":
                return w.isChecked()
        except (AttributeError, RuntimeError, TypeError):
            return None
        return None

    def _top(self):
        client = self.o.__dict__.get("_client")
        return self.o.height() - client.height() if client is not None else 0

    @staticmethod
    def _hold(name, w, prop):
        """A state / storyboard sets this geometry: Anchor / Dock leave it alone until release()."""
        if name:
            held = getattr(w, "_rad_held", None)
            if held is None:
                held = set()
                w._rad_held = held
            held.add(prop)

    def release(self, name, prop=None):
        """A state / storyboard gave the geometry back: Anchor / Dock place the control again."""
        if not name:
            return
        try:
            w = self.w(name)
            held = getattr(w, "_rad_held", None)
            if not held:
                return
            if prop is None:
                held.clear()
            else:
                held.discard(prop)
            host = w.parentWidget()
            for lay in (host.children() if host is not None else []):
                if type(lay).__name__ == "_Layout" and any(it[0] is w for it in lay.items):
                    lay.apply()
        except (AttributeError, RuntimeError):
            pass

    def set(self, name, prop, v):
        if v is None:
            return
        if prop == "Visible" and name and not self.quiet and self.vis_hook is not None \
                and self.vis_hook(name, bool(v)):
            return                                  # an "On show" / "On hide" animation takes over
        try:
            w = self.w(name)
            if prop == "Text":
                if not name:
                    w.setWindowTitle(str(v))
                elif isinstance(w, QPlainTextEdit):
                    w.setPlainText(str(v))
                elif isinstance(w, QGroupBox):
                    w.setTitle(str(v))
                elif isinstance(w, QComboBox):
                    if w.isEditable():
                        w.setEditText(str(v))
                    elif w.findText(str(v)) >= 0:
                        w.setCurrentIndex(w.findText(str(v)))
                elif hasattr(w, "setText"):
                    w.setText(str(v))
            elif prop in ("Left", "Top"):
                self._hold(name, w, prop)
                w.move(int(v) if prop == "Left" else w.x(), int(v) if prop == "Top" else w.y())
            elif prop in ("Width", "Height"):
                self._hold(name, w, prop)
                top = 0 if name else self._top()
                w.resize(int(v) if prop == "Width" else w.width(), int(v) + top if prop == "Height" else w.height())
            elif prop in ("BackColor", "ForeColor"):
                d = self._colors.setdefault(name, {})
                if v:
                    d[prop] = str(v)
                else:
                    d.pop(prop, None)
                self._restyle(name, w)
            elif prop == "Visible":
                w.setVisible(bool(v))
            elif prop in ("FontSize", "FontBold", "FontItalic"):
                f = w.font()
                if prop == "FontSize":
                    f.setPointSize(max(1, int(v)))
                elif prop == "FontBold":
                    f.setBold(bool(v))
                else:
                    f.setItalic(bool(v))
                w.setFont(f)
            elif prop == "Opacity":
                if not name:
                    w.setWindowOpacity(float(v))
                else:
                    eff = w.graphicsEffect()
                    if not isinstance(eff, QGraphicsOpacityEffect):
                        eff = QGraphicsOpacityEffect(w)
                        w.setGraphicsEffect(eff)
                    eff.setOpacity(max(0.0, min(1.0, float(v))))
            elif prop == "Value":
                w.setValue(int(float(v)))
            elif prop == "Checked":
                w.setChecked(bool(v))
        except (AttributeError, RuntimeError, TypeError, ValueError):
            pass

    def _restyle(self, name, w):
        if name not in self._base_ss:
            self._base_ss[name] = w.styleSheet()
        d = self._colors.get(name, {})
        rules = ""
        if d.get("BackColor"):
            rules += f"background-color:{d['BackColor']};"
        if d.get("ForeColor"):
            rules += f"color:{d['ForeColor']};"
        if not rules:
            w.setStyleSheet(self._base_ss[name])
            return
        if not w.objectName():
            w.setObjectName(name or "rad_form")
        sel = f"#{w.objectName()}" + (", #client" if not name else "")
        w.setStyleSheet(self._base_ss[name] + f"\n{sel} {{ {rules} }}")

    def set_items(self, name, items):
        w = self.w(name)
        w.clear()
        w.addItems([str(i) for i in items])

    def set_rows(self, name, columns, rows):
        w = self.w(name)
        w.clear()
        w.setColumnCount(max(1, len(columns)))
        w.setHorizontalHeaderLabels([str(c) for c in columns])
        w.setRowCount(len(rows))
        for r, row in enumerate(rows):
            for c, text in enumerate(row):
                w.setItem(r, c, QTableWidgetItem(str(text)))

    def rgb(self, name, prop, value):
        c = _rad_rgb_hex(value)
        if c is not None:
            return c
        if value:
            q = QColor(str(value))
        else:
            w = self.w(name)
            q = w.palette().color(w.backgroundRole() if prop == "BackColor" else w.foregroundRole())
        return (q.red(), q.green(), q.blue()) if q.isValid() else None

    def later(self, ms, fn):
        QTimer.singleShot(int(ms), self.o, fn)

    def bind(self, name, event, fn):
        """Animation triggers: event "click" / "enter" / "leave" of a control ("" = the form) calls fn()."""
        self._events.append(_RadFxEvents(self.w(name), event, fn))

    def parent_bg(self, name):
        try:
            w = self.w(name)
            host = w.parentWidget() or w
            return host.palette().color(host.backgroundRole()).name()
        except (AttributeError, RuntimeError):
            return None

    def on_select(self, name, fn):
        w = self.w(name)
        sig = w.currentRowChanged if isinstance(w, QListWidget) else w.currentIndexChanged
        sig.connect(lambda i: i >= 0 and fn(i))

    def hook(self, name, vsm, disabled=False):
        self._events.append(_RadStateEvents(self.w(name), name, vsm))


